# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError

def make_shift(worker, start, end, day="mon"):
    return Shift(worker, day, Span(start * 60, end * 60))

class TimesheetTests(unittest.TestCase):
    def test_empty_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_name_raises(self):
        for name in ("", "   "):
            with self.assertRaises(ProjectError):
                timesheet_lines([make_shift(name, 9, 17)])

    def test_one_decimal_and_singular(self):
        shifts = [Shift("Ana", "mon", Span(540, 1000))]
        self.assertEqual(
            timesheet_lines(shifts),
            ["Ana: 1 shift, 7.7 hours"]
        )

    def test_busiest_first(self):
        shifts = [
            make_shift("Ben", 9, 11),
            make_shift("Cy", 9, 17),
            make_shift("Ana", 9, 13),
            make_shift("Ana", 9, 13, "tue")
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Ana: 2 shifts, 8.0 hours",
                "Cy: 1 shift, 8.0 hours",
                "Ben: 1 shift, 2.0 hours"
            ]
        )

if __name__ == "__main__":
    unittest.main()
